<?php $e=static fn(mixed $v):string=>htmlspecialchars((string)$v,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8'); ?>
<!doctype html><html lang="de"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Nachrichten – MeldeVerkehr</title><style>body{font-family:system-ui,sans-serif;background:#f5f7fa;color:#172033;margin:0}main{max-width:900px;margin:28px auto;padding:20px}.card{background:#fff;border:1px solid #dfe5ec;border-radius:15px;padding:20px;margin-bottom:14px}.msg{border-top:1px solid #e5e9ee;padding:11px 0}input,textarea{width:100%;box-sizing:border-box;padding:9px;border:1px solid #bac5d1;border-radius:8px;margin:4px 0}button{padding:9px 13px;border:0;border-radius:9px;background:#172033;color:#fff;font-weight:700}.danger{background:#8e1f1f}.message,.error{padding:10px;border-radius:8px}.message{border:1px solid #8fb799}.error{border:1px solid #c99}.muted{color:#66758a}</style></head><body><main><p><a href="/community">← Community</a></p><h1>Nachrichten</h1><?php if($message):?><div class="message"><?= $e($message) ?></div><?php endif;?><?php if($error):?><div class="error"><?= $e($error) ?></div><?php endif;?>
<section class="card"><h2>Nachricht senden</h2><form method="post" action="/community/messages"><input type="hidden" name="_csrf" value="<?= $e($csrf) ?>"><input name="username" placeholder="Benutzername" required><textarea name="body" maxlength="10000" required></textarea><button type="submit">Senden</button></form><form method="post" action="/community/blocks"><input type="hidden" name="_csrf" value="<?= $e($csrf) ?>"><input name="username" placeholder="Benutzername blockieren" required><button class="danger" type="submit">Blockieren</button></form></section>
<section class="card"><h2>Verlauf / Anfragen</h2><?php foreach($messages as $m):?><div class="msg"><strong>@<?= $e($m['sender_username']) ?> → @<?= $e($m['recipient_username']) ?></strong> · <?= $e($m['status']) ?><p><?= nl2br($e($m['body'])) ?></p><small class="muted"><?= $e($m['created_at']) ?></small><?php if($m['status']==='REQUEST'&&$m['recipient_user_id']===$userId):?><form method="post" action="/community/messages/<?= rawurlencode($m['id']) ?>/accept"><input type="hidden" name="_csrf" value="<?= $e($csrf) ?>"><button type="submit">Anfrage annehmen</button></form><?php endif;?></div><?php endforeach;?></section>
</main></body></html>